def-struct-hyp(
    __list__(Type.annotation(@P, Set(T)), Type.annotation(@$\lt$, Rl(P, P))),
    Set.order.linear(P, $\lt$),
    __enum__(
        Set.order.partial(P, $\lt$),
        Logic.forall-typed(@p, P, Logic.forall-typed(@q, P, Logic.or(Eq(p, q), Logic.or(Rl.apply($\lt$, p, q), Rl.apply($\lt$, q, p)))))
    )
)
